// upsertReturned runs an upsert's statement, query with values, and scans
// each row it returns and whether it inserted it.
func (r *RecipeSnapshotEntryRepository) upsertReturned(ctx context.Context, query string, values []any) ([]*types.RecipeSnapshotEntry, []bool, error) {
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, nil, fmt.Errorf("failed to execute upsert: %w", err)
	}
	defer rows.Close()
	var returned []*types.RecipeSnapshotEntry
	var inserted []bool
	for rows.Next() {
		var flag bool
		row, err := r.scanReturned(rows, &flag)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to scan result: %w", err)
		}
		returned = append(returned, row)
		inserted = append(inserted, flag)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, fmt.Errorf("error iterating results: %w", err)
	}
	return returned, inserted, nil
}

// rowsOfKeys reads the rows that hold keys, each the values of the unique
// key on an input's insert binds, among the rows the key's index holds, in
// the inputs' order: the rows an upsert only if changed left as they were
// (D89). A key no live row holds is ErrNotFound.
func (r *RecipeSnapshotEntryRepository) rowsOfKeys(ctx context.Context, on RecipeSnapshotEntryUniqueKey, keys [][]any, inputs []*types.RecipeSnapshotEntry) ([]*types.RecipeSnapshotEntry, error) {
	tuples, values := upsertKeyTuples(keys)
	query := fmt.Sprintf(recipeSnapshotEntryUniqueKeys[on].rows, strings.Join(tuples, ", "))
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the rows the upsert left: %w", err)
	}
	defer rows.Close()
	found := map[string]*types.RecipeSnapshotEntry{}
	for rows.Next() {
		row, err := r.scanReturned(rows, nil)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}
		if text, ok := recipeSnapshotEntryKeyOf(on, row); ok {
			found[text] = row
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}
	out := make([]*types.RecipeSnapshotEntry, len(inputs))
	for i, input := range inputs {
		text, _ := recipeSnapshotEntryKeyOf(on, input)
		row := found[text]
		if row == nil {
			return nil, fmt.Errorf("the RecipeSnapshotEntry row that holds the key %s is deleted: %w", string(on), ErrNotFound)
		}
		out[i] = row
	}
	return out, nil
}

